*{box-sizing:border-box}:root{color-scheme:light;--paper:#faf6ee;--ink:#2b302c;--muted:#727a70;--line:#daddd2;--orange:#b94e2c;--pale:#f5e5d6;--green:#557157}body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 Arial,sans-serif}button,select{font:inherit}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:25px 38px;border-bottom:1px solid var(--line)}.brand{font-size:17px;font-weight:800;letter-spacing:1.5px}.brand b{color:var(--orange)}.badge{font-size:10px;color:var(--muted);border:1px solid var(--line);border-radius:30px;padding:7px 12px}main{max-width:1100px;padding:36px 38px 25px;margin:auto}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:bold;color:var(--orange)}h1{font-family:Georgia,serif;font-weight:400;font-size:46px;letter-spacing:-1.2px;line-height:1.1;margin:13px 0 15px;max-width:730px}.intro{color:var(--muted);font-size:13px;max-width:670px;line-height:1.7;margin:0 0 28px}.workspace{display:grid;grid-template-columns:1.04fr 1fr;gap:25px}.form,.result{border:1px solid var(--line);border-radius:13px;padding:23px}.form{background:#fffdf8}.result{background:#eef1e8}.step{display:inline-block;background:var(--pale);color:var(--orange);border-radius:4px;padding:3px 7px;font-size:9px;font-weight:700;letter-spacing:1px}h2{font-size:20px;margin:10px 0 17px;line-height:1.3}.label{display:block;font-size:11px;font-weight:bold;margin:16px 0 7px}.field,select{border:1px solid #cfd4c6;border-radius:7px;width:100%;padding:11px 12px;background:white;color:var(--ink);font-size:12px}.field{color:var(--muted)}.form-note{font-size:10px;color:var(--muted);margin:14px 0 0}.tags{display:flex;flex-wrap:wrap;gap:7px;margin:17px 0}.tag{font-size:10px;padding:6px 9px;border-radius:20px;background:white;border:1px solid #cad4c4}.status{display:flex;align-items:flex-start;gap:11px;padding:14px 0;border-top:1px solid #d1d8c8}.status .dot{width:8px;height:8px;flex:0 0 8px;background:var(--green);border-radius:50%;margin-top:5px}.status strong{font-size:12px;display:block}.status p{font-size:11px;color:var(--muted);margin:3px 0 0}.status.sample .dot{background:var(--orange)}button{cursor:pointer}.action{width:100%;border:0;background:var(--ink);color:white;border-radius:7px;padding:11px 13px;font-size:12px;margin-top:15px}.action:disabled{background:#576753;cursor:default}#notice{font-size:10px;line-height:1.7;color:var(--muted);margin-top:10px;min-height:33px}.limits{margin-top:23px;padding-top:17px;border-top:1px solid var(--line);font-size:10px;line-height:1.8;color:var(--muted)}footer{display:flex;justify-content:space-between;gap:14px;margin-top:20px;color:var(--muted);font-size:9px}
@media(max-width:700px){header{padding:21px}.brand{font-size:13px}.badge{font-size:9px;padding:5px 9px}main{padding:29px 21px 24px}h1{font-size:38px}.workspace{grid-template-columns:1fr;gap:17px}.form,.result{padding:19px}footer{flex-direction:column}}
@page{size:270mm 254mm;margin:0}@media print{body{print-color-adjust:exact;-webkit-print-color-adjust:exact}main{padding-top:31px}.intro{margin-bottom:24px}.form,.result{padding:21px}}
.samplebar{padding:8px 5%;background:#e6eade;color:#475b46;display:flex;justify-content:space-between;gap:15px;font:11px Arial}.samplebar a{font-weight:bold;text-decoration:underline;color:inherit}@media(max-width:650px){.samplebar{font-size:9px}}
.hero-art{float:right;width:190px;height:130px;margin:0 0 15px 25px}.more{padding:25px 0 0;border-top:1px solid var(--line);margin-top:30px;display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.more h3{font-size:15px}.more p{font-size:12px;color:var(--muted)}.more a{color:var(--orange)}@media(max-width:700px){.hero-art{width:100px;height:85px}.more{grid-template-columns:1fr;gap:5px}}
.wp-site-blocks{padding:0!important}.wp-block-post-content{margin:0!important}

const role=document.getElementById('role'),availability=document.getElementById('availability');
function update(){
 document.getElementById('role-tag').textContent=role.value;
 document.getElementById('time-tag').textContent=availability.selectedOptions[0].textContent;
 document.getElementById('route-title').textContent={'Kitchen preparation':'Join the kitchen team','Food collection':'Keep the pantry stocked','Welcoming guests':'Make everyone feel welcome'}[role.value];
 document.getElementById('notice').textContent='';
}
role.addEventListener('change',update);availability.addEventListener('change',update);
document.getElementById('preview-volunteer').addEventListener('click',()=>{
 document.getElementById('notice').textContent='Hello Open Table team, I would like to help with '+role.value.toLowerCase()+'. I can join '+availability.selectedOptions[0].textContent.toLowerCase()+'. Please tell me about the next introduction session.';
});
